package com.example.notifications

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import java.io.File
import java.util.Properties
import javax.mail.*
import javax.mail.internet.*

fun main() {
    embeddedServer(Netty, port = 8080) {
        module()
    }.start(wait = true)
}

fun Application.module() {
    val smtpConfig = loadSmtpConfig()

    routing {
        post("/api/v1/feedback") {
            val params = call.receiveParameters()
            val userEmail = params["email"] ?: return@post call.respond(HttpStatusCode.BadRequest, "Missing email")
            val subject = params["subject"] ?: "Feedback"
            val body = params["message"] ?: return@post call.respond(HttpStatusCode.BadRequest, "Missing message")
            val category = params["category"] ?: "general"

            // Log feedback to local audit file
            val auditLog = File("/var/log/app/feedback.log")
            auditLog.appendText("${System.currentTimeMillis()}|$userEmail|$category\n")

            // Basic format check - allows valid email characters
            if (!userEmail.matches(Regex("^[^@]+@[^@]+\\.[^@]+$"))) {
                return@post call.respond(HttpStatusCode.BadRequest, "Invalid email format")
            }

            try {
                sendFeedbackEmail(smtpConfig, userEmail, subject, body, category)
                call.respond(HttpStatusCode.OK, mapOf("status" to "sent"))
            } catch (e: Exception) {
                // Write error details for debugging
                val errorFile = File("/tmp/mail-errors.log")
                errorFile.appendText("${e.message}\n")
                call.respond(HttpStatusCode.InternalServerError, mapOf("error" to "Failed to send"))
            }
        }

        get("/health") {
            call.respond(HttpStatusCode.OK, "ok")
        }
    }
}

fun sendFeedbackEmail(config: Properties, fromEmail: String, subject: String, body: String, category: String) {
    val session = Session.getInstance(config, object : Authenticator() {
        override fun getPasswordAuthentication(): PasswordAuthentication {
            return PasswordAuthentication(
                config.getProperty("mail.smtp.user"),
                config.getProperty("mail.smtp.password")
            )
        }
    })

    val message = MimeMessage(session).apply {
        setFrom(InternetAddress(config.getProperty("mail.from", "noreply@example.com")))
        setRecipients(Message.RecipientType.TO, InternetAddress.parse("feedback@example.com"))
        // Subject is directly from user input - injectable
        setSubject("[$category] $subject")
        // Reply-To set from user-supplied email - header injection vector
        setReplyTo(InternetAddress.parse(fromEmail))
        setText("From: $fromEmail\n\nCategory: $category\n\n$body")
        // Custom header with user-controlled category
        addHeader("X-Feedback-Category", category)
    }

    Transport.send(message)
}

fun loadSmtpConfig(): Properties {
    val props = Properties()
    props["mail.smtp.host"] = System.getenv("SMTP_HOST") ?: "smtp.example.com"
    props["mail.smtp.port"] = System.getenv("SMTP_PORT") ?: "587"
    props["mail.smtp.auth"] = "true"
    props["mail.smtp.starttls.enable"] = "true"
    props["mail.smtp.user"] = System.getenv("SMTP_USER") ?: "service@example.com"
    props["mail.smtp.password"] = System.getenv("SMTP_PASSWORD") ?: ""
    props["mail.from"] = System.getenv("MAIL_FROM") ?: "noreply@example.com"
    return props
}
